import hashlib, json
from pathlib import Path
root = Path('products/distribution/catalogue-referral')
for name in ('item-4-release-binding.json', '2026-11-19-candidate-live-comparison.json', 'live-pilot-link-check.json', 'operator-handoff.md', '2026-11-19-direct-catalogue-readback.html'):
    path = root / name
    data = path.read_bytes()
    record = {'path': str(path), 'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}
    if path.suffix == '.json':
        record['evidence'] = json.loads(data)
    print(json.dumps(record, ensure_ascii=False))
